'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const types={lost:'Kaybedildi',found:'Bulundu',free:'Ücretsiz veriliyor',pet_lost:'Hayvan kayıp',pet_found:'Hayvan bulundu',adoption:'Sahiplendirme'};
const statuses={open:'Açık',reserved:'Doğrulandı · Ayrıldı',delivered:'Teslim edildi',closed:'Kapalı',archived:'Süresi doldu',hidden:'Gizlendi',deleted:'Silindi',pending:'Doğrulanıyor',accepted:'Kabul edildi',rejected:'Reddedildi',reviewing:'İnceleniyor',resolved:'Çözüldü',approved:'Onaylı',active:'Aktif',restricted:'Kısıtlı'};
const roles={member:'Üye',staff:'Kurum çalışanı',location_admin:'Yer yöneticisi',org_admin:'Kurum yöneticisi',user:'Kullanıcı',moderator:'Güvenlik moderatörü',admin:'Platform yöneticisi'};
const categories=['Çanta ve cüzdan','Telefon, tablet ve bilgisayar','Anahtar ve kart','Kimlik ve diğer evrak','Kıyafet ve aksesuar','Kitap ve okul eşyası','Çocuk eşyası ve oyuncak','Gözlük ve takı','Ev eşyası','Diğer','Kedi','Köpek','Kuş','Diğer hayvan'];
const cities=['İstanbul','Ankara','İzmir','Adana','Adıyaman','Afyonkarahisar','Ağrı','Aksaray','Amasya','Antalya','Ardahan','Artvin','Aydın','Balıkesir','Bartın','Batman','Bayburt','Bilecik','Bingöl','Bitlis','Bolu','Burdur','Bursa','Çanakkale','Çankırı','Çorum','Denizli','Diyarbakır','Düzce','Edirne','Elazığ','Erzincan','Erzurum','Eskişehir','Gaziantep','Giresun','Gümüşhane','Hakkâri','Hatay','Iğdır','Isparta','Kahramanmaraş','Karabük','Karaman','Kars','Kastamonu','Kayseri','Kırıkkale','Kırklareli','Kırşehir','Kilis','Kocaeli','Konya','Kütahya','Malatya','Manisa','Mardin','Mersin','Muğla','Muş','Nevşehir','Niğde','Ordu','Osmaniye','Rize','Sakarya','Samsun','Siirt','Sinop','Sivas','Şanlıurfa','Şırnak','Tekirdağ','Tokat','Trabzon','Tunceli','Uşak','Van','Yalova','Yozgat','Zonguldak'];
const icon=(name='box')=>{const paths={box:'<path d="m3 7 9-4 9 4v10l-9 4-9-4Z"/><path d="m3 7 9 4 9-4M12 11v10M7.5 5 17 9"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',found:'<path d="m5 12 4 4L20 5M4 4h8M4 4v6M20 14v6H4v-4"/>',gift:'<rect x="3" y="8" width="18" height="4" rx="1"/><path d="M5 12v9h14v-9M12 8v13M12 8s-8-1-6-5 6 5 6 5 8-1 6-5-6 5-6 5"/>',pet:'<ellipse cx="12" cy="16" rx="6" ry="4"/><ellipse cx="5" cy="9" rx="2" ry="3"/><ellipse cx="10" cy="5" rx="2" ry="3"/><ellipse cx="16" cy="5" rx="2" ry="3"/><ellipse cx="21" cy="10" rx="2" ry="3"/>'};return `<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">${paths[name]||paths.box}</svg>`;};
const opts=(values,current='',first='Seçiniz')=>`<option value="">${esc(first)}</option>`+Object.entries(Array.isArray(values)?Object.fromEntries(values.map(v=>[v,v])):values).map(([k,v])=>`<option value="${esc(k)}" ${String(current)===k?'selected':''}>${esc(v)}</option>`).join('');
const date=v=>v?new Date(v.includes(' ')?v.replace(' ','T'):v).toLocaleDateString('tr-TR'):'';
const badge=(v,label)=>`<span class="badge ${esc(v)}">${esc(label||types[v]||statuses[v]||v)}</span>`;
const empty=(title,body='',link='')=>`<div class="empty"><h3>${esc(title)}</h3><p>${esc(body)}</p>${link}</div>`;
const title=(heading,sub='',button='')=>`<div class="section-title"><div><p class="eyebrow">V-404 / ${esc(heading.toLocaleUpperCase('tr'))}</p><h1>${esc(heading)}</h1>${sub?`<p class="muted">${esc(sub)}</p>`:''}</div>${button}</div>`;
let state={user:null,csrf:'',local:false},poll=null,localCode='',orgCache=null,photos=[],renderToken=0;
async function api(action,data=null,params={}){const url='api.php?'+new URLSearchParams({action,...params});const config={credentials:'same-origin',headers:{}};if(data!==null){config.method='POST';config.headers['X-CSRF-Token']=state.csrf;if(data instanceof FormData)config.body=data;else{config.headers['Content-Type']='application/json';config.body=JSON.stringify(data);}}const res=await fetch(url,config);let result;try{result=await res.json();}catch{throw Error('Sunucu yanıtı okunamadı. WampServer ve PHP ayarlarını kontrol edin.');}if(!res.ok)throw Error(result.error||'İşlem tamamlanamadı.');return result;}
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className=error?'error':'';el.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.style.display='none',6000);}
function modal(html){$('#modal-body').innerHTML=html;$('#modal').showModal();}$('#modal-close').onclick=()=>$('#modal').close();
function bindForm(id,fn){const form=document.getElementById(id);if(!form)return;form.onsubmit=async e=>{e.preventDefault();const buttons=[...form.querySelectorAll('button[type=submit],button:not([type])')];buttons.forEach(b=>b.disabled=true);try{await fn(Object.fromEntries(new FormData(form)),form);}catch(e){toast(e.message,true);}finally{buttons.forEach(b=>b.disabled=false);}};}
async function session(){state={...state,...await api('session')};$('#account').textContent=state.user?state.user.name.split(' ')[0]:'Giriş yap';$('#account').href=state.user?'#profile':'#login';$('#bell').hidden=!state.user;$('#announcement').hidden=!state.announcement;$('#announcement').textContent=state.announcement||'';}
function needUser(){if(!state.user){location.hash='login';return false;}if(!Number(state.user.verified)){location.hash='verify';return false;}return true;}
function userTabs(active){return `<div class="tabs">${[['profile','Profilim'],['mine','İlanlarım'],['matches','Eşleşmeler'],['claims','Talepler ve sohbet'],['notifications','Bildirimler'],['organizations','Kurumlarım'],['support','Başvurularım']].map(([r,t])=>`<a class="${r===active?'active':''}" href="#${r}">${t}</a>`).join('')}</div>`;}
function card(l){return `<a class="listing-card" href="#listing/${l.id}"><div class="card-picture">${l.photos?.length?`<img src="api.php?action=photo&id=${l.photos[0].id}" alt="${esc(l.title)}" loading="lazy">`:icon(l.type.startsWith('pet')||l.type==='adoption'?'pet':'box')}</div><div class="card-body">${badge(l.type)}<h3>${esc(l.title)}</h3><p>${esc(l.city)} · ${esc(l.district)}</p><div class="card-bottom"><span>${esc(l.org_name||'Genel ağ')}</span><span>${date(l.event_date)}</span></div></div></a>`;}
async function home(params){const data=await api('listings',null,Object.fromEntries(params));const orgs=await api('organizations');orgCache=orgs;$('#main').innerHTML=`<section class="intro"><div><p class="eyebrow">KAYIP EŞYA VE DAYANIŞMA AĞI</p><h1>Kaybolduysa, <span class="red">burada bul.</span></h1><p>Bir eşya, bir iz, yeniden buluşma ihtimali.</p></div><p class="privacy-note">Kişisel bilgileriniz gizli kalır.<br>Teslim, doğrulamayla başlar.</p></section><div class="action-grid">${[['lost','search','Kaybettim','Aramaya bir ilanla başla'],['found','found','Buldum','Sahibine ulaşmasına yardım et'],['free','gift','Ücretsiz paylaş','Kullanmadığın eşya işe yarasın'],['animals','pet','Hayvanlar','Kayıp, bulunan ve sahiplendirme']].map(([type,ico,label,desc])=>`<a class="action-card" href="#${type==='animals'?'animals':'create/'+type}"><span class="action-icon">${icon(ico)}</span><span><strong>${label}</strong><small>${desc}</small></span></a>`).join('')}</div><form id="search" class="searchbar"><span style="width:25px">${icon('search')}</span><input name="q" aria-label="İlan ara" placeholder="Eşya, kategori veya kurum ara…" value="${esc(params.get('q')||'')}"><select name="city" aria-label="Şehir">${opts(cities,params.get('city'),'Tüm şehirler')}</select><button class="primary">İlan ara</button></form><div class="browse-layout"><aside class="filters"><form id="filters"><h3>Aramanı daralt</h3><label>İlan türü<select name="type">${opts(types,params.get('type'),'Tüm ilanlar')}</select></label><label>Kategori<select name="category">${opts(categories,params.get('category'),'Tüm kategoriler')}</select></label><label>Yaklaşık bölge<input name="district" value="${esc(params.get('district')||'')}" placeholder="Örn. Kadıköy"></label><label>Kurum<select name="org_id">${opts(Object.fromEntries(orgs.items.map(o=>[o.id,o.name])),params.get('org_id'),'Tüm kurumlar')}</select></label><label>Yayın alanı<select name="scope">${opts({public:'Genel ağ'},params.get('scope'),'Tüm erişilebilir ilanlar')}</select></label><div class="divider"></div><label>Başlangıç tarihi<input type="date" name="from" value="${esc(params.get('from')||'')}"></label><label>Bitiş tarihi<input type="date" name="to" value="${esc(params.get('to')||'')}"></label><button class="primary">Filtrele</button><a class="button quiet" style="width:100%;margin-top:8px" href="#home">Temizle</a></form></aside><section><div class="result-head"><h2>${params.size?'Arama sonuçları':'Son ilanlar'} <small>(${data.total})</small></h2><button class="mobile-filters small" data-action="filters">Filtreler</button><span class="count">En yeni ilanlar önce</span></div><div class="card-grid">${data.items.length?data.items.map(card).join(''):empty('Henüz ilan bulunamadı.','Filtrelerini değiştirebilir veya ilk ilanı sen oluşturabilirsin.','<a class="button primary" href="#create">İlan oluştur</a>')}</div>${data.total>12?`<div class="pagination">${data.page>1?`<button data-page="${data.page-1}">Önceki</button>`:''}<span>Sayfa ${data.page} / ${Math.ceil(data.total/12)}</span>${data.page*12<data.total?`<button data-page="${data.page+1}">Sonraki</button>`:''}</div>`:''}</section></div><section class="how-strip"><article><span class="step">1</span><div><h3>İlanını oluştur</h3><p>Eşyayı ve yaklaşık bölgeyi belirt. Özel ayrıntılar gizli kalsın.</p></div></article><article><span class="step">2</span><div><h3>Olası eşleşmeleri incele</h3><p>Benzer ilanları karşılaştır; sahipliği bir ayrıntıyla doğrula.</p></div></article><article><span class="step">3</span><div><h3>Güvenle teslim et</h3><p>Kamusal bir noktada buluş. İki taraf da teslimi onaylasın.</p></div></article></section>`;
const filter=d=>{const p=new URLSearchParams(params);p.delete('page');Object.entries(d).forEach(([k,v])=>v?p.set(k,v):p.delete(k));location.hash='home?'+p;};bindForm('search',filter);bindForm('filters',filter);$$('[data-page]').forEach(b=>b.onclick=()=>{params.set('page',b.dataset.page);location.hash='home?'+params;});}
async function auth(mode){const register=mode==='register';$('#main').innerHTML=`<section class="auth panel"><p class="eyebrow">${register?'V-404’E KATIL':'TEKRAR HOŞ GELDİN'}</p><h1>${register?'İyiliğe bir adım.':'Giriş yap'}</h1><p class="muted">${register?'İlan oluştur, eşleşmeleri takip et ve güvenle iletişim kur.':'İlanların, eşleşmelerin ve görüşmelerin burada.'}</p><form id="auth">${register?'<label>Görünen ad<input name="name" maxlength="80" required autocomplete="name"></label>':''}<label>E-posta<input name="email" type="email" maxlength="190" required autocomplete="email"></label><label>Parola<input name="password" type="password" minlength="${register?10:1}" maxlength="200" required autocomplete="${register?'new-password':'current-password'}"></label>${register?'<label class="check"><input type="checkbox" name="adult" required><span>18 yaşından büyüğüm. Çocuk adına işlemleri veli veya yetkili personel olarak yürütürüm.</span></label><label class="check"><input type="checkbox" name="consent" required><span><a href="#rules" target="_blank">Kullanım kurallarını</a> ve <a href="#privacy" target="_blank">gizlilik açıklamasını</a> okudum, kabul ediyorum.</span></label>':''}<button class="primary">${register?'Hesap oluştur':'Giriş yap'}</button></form><div class="divider"></div><p class="muted">${register?'Zaten hesabın var mı? <a href="#login"><strong>Giriş yap</strong></a>':'Yeni misin? <a href="#register"><strong>Hesap oluştur</strong></a>'}</p><small class="muted">İlanları hesap açmadan da inceleyebilirsin.</small></section>`;bindForm('auth',async d=>{const r=await api(mode,d);localCode=r.local_code||'';await session();location.hash=state.user.verified?(sessionStorage.getItem('v404-admin-login')?'admin':'mine'):'verify';sessionStorage.removeItem('v404-admin-login');toast(r.message);});}
async function verify(){if(!state.user){location.hash='login';return;}$('#main').innerHTML=`<section class="auth panel"><h1>E-postanı doğrula</h1><p class="muted">${esc(state.user.email)} için 6 haneli kodu gir. Kod 15 dakika geçerlidir.</p>${state.local?`<div class="notice"><strong>Yerel geliştirme posta kutusu</strong><p>Bu modda gerçek e-posta gönderilmez.</p><div class="code" id="local-code">${esc(localCode||'Yeni kod almak için aşağıdaki düğmeyi kullan.')}</div></div>`:''}<form id="verify"><label>Doğrulama kodu<input name="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required autocomplete="one-time-code"></label><button class="primary">Hesabımı doğrula</button></form><button data-action="resend" style="margin-top:12px">Yeni kod gönder</button></section>`;bindForm('verify',async d=>{await api('verify',d);await session();location.hash='mine';toast('Hesabın doğrulandı.');});}
async function create(type='lost',editId=null){if(!needUser())return;photos=[];const l=editId?await api('listing',null,{id:editId}):{type:types[type]?type:'lost',event_date:new Date().toLocaleDateString('en-CA'),alert:1};if(editId&&!l.can_manage)throw Error('İlanı düzenleme yetkiniz yok.');const orgs=await api('organizations');const memberships=orgs.memberships.filter(m=>m.status==='approved'&&m.org_status==='approved');const orgOptions=Object.fromEntries(memberships.map(m=>[m.org_id,m.name]));$('#main').innerHTML=`<div class="form-wrap"><a class="breadcrumb" href="#${editId?'listing/'+editId:'home'}">← ${editId?'İlana dön':'İlanlara dön'}</a>${title(editId?'İlanı düzenle':'Yeni ilan oluştur','Herkese açık bilgileri yaz; ayırt edici ayrıntıları gizli tut.')}<form id="listing-form"><section class="panel"><h2>1. İlan bilgileri</h2><label>İlan türü<select name="type" id="listing-type" required ${editId?'disabled':''}>${opts(types,l.type)}</select></label>${editId?`<input type="hidden" name="type" value="${l.type}"><input type="hidden" name="id" value="${editId}">`:''}<div class="form-grid"><label class="full">Başlık<input name="title" placeholder="Örn. Kadıköy'de bulunan lacivert sırt çantası" value="${esc(l.title)}" maxlength="120" required></label><label>Kategori / Hayvan türü<select name="category" required>${opts(categories,l.category)}</select></label><label>Yaklaşık tarih<input type="date" name="event_date" value="${esc(l.event_date||new Date().toISOString().slice(0,10))}" max="${new Date().toISOString().slice(0,10)}" required></label><label class="full">Açıklama<textarea name="description" maxlength="4000" required placeholder="Görünen özellikleri anlat. Telefon, ev adresi ve sosyal medya hesabı yazma.">${esc(l.description)}</textarea></label><label>Renk<input name="color" maxlength="60" value="${esc(l.color)}"></label><label>Marka<input name="brand" maxlength="80" value="${esc(l.brand)}"></label><label>Model<input name="model" maxlength="80" value="${esc(l.model)}"></label><label class="condition-field">Eşyanın durumu<input name="condition_text" maxlength="1500" value="${esc(l.condition_text)}" placeholder="Yeni, kullanılmış, kusurları…"></label><label class="full health-field">Bakım ve bilinen sağlık bilgileri<textarea name="health" maxlength="1500">${esc(l.health)}</textarea></label></div></section><section class="panel"><h2>2. Yaklaşık konum ve gizli ayrıntılar</h2><div class="form-grid"><label>Şehir<select name="city" required>${opts(cities,l.city)}</select></label><label>Yaklaşık bölge<input name="district" maxlength="100" required value="${esc(l.district)}" placeholder="İlçe / semt; açık adres yazmayın"></label><label class="full secret-field">Gizli doğrulama bilgisi<textarea name="secret" maxlength="1500" placeholder="Yalnızca sahibinin bilebileceği bir ayrıntı…">${esc(l.secret)}</textarea><small>İlan sayfasında yayımlanmaz. Sahiplik talebinde bulunan kişi kendi kanıtını ayrıca gönderir.</small></label><label class="full route-field">Son görülen yer, güzergâh ve sefer bilgisi (isteğe bağlı)<textarea name="route" maxlength="3000" placeholder="Uğradığın noktalar ve yaklaşık saatler. Canlı konum takip edilmez.">${esc(l.route)}</textarea><small>Yalnızca eşleştirme ve ilan sorumlusu için saklanır, karşı tarafa gösterilmez.</small></label><label class="full custody-field">Eşya nerede muhafaza ediliyor?<select name="custody">${opts(['Kendi muhafazamda','Kurumun kayıp eşya biriminde','Otogar danışmasında','Okul güvenliğinde','Başka bir kamusal teslim noktasında'],l.custody)}</select><small>Bu genel bilgi ilan sayfasında görünür.</small></label><label class="full">Gizli teslim / konum notu<textarea name="private_location" maxlength="1500" placeholder="Gerekliyse kurum içi dolap veya muhafaza ayrıntısı…">${esc(l.private_location)}</textarea><small>Yalnızca ilan sahibi ve yetkili kurum görevlisi görebilir.</small></label></div><div class="map-section"><h3>Haritada konum ve güzergâh (isteğe bağlı)</h3><p class="hint">Tam nokta ve rota yalnızca ilan sorumlusuna ve yetkili kurum çalışanına açıktır. Ziyaretçiler yaklaşık 1 km hassasiyetinde konumu görür. Harita internet kullanır; açıldığında OpenStreetMap'e bağlantı kurulur.</p><input type="hidden" name="latitude" value="${esc(l.latitude)}"><input type="hidden" name="longitude" value="${esc(l.longitude)}"><input type="hidden" name="route_points" value="${esc(l.route_points||'[]')}"><button type="button" id="open-map">Haritayı aç</button><div id="map-controls" hidden><label>Haritaya tıklama işlemi<select id="map-mode"><option value="location">İlgili konumu işaretle</option><option value="route">Güzergâha nokta ekle</option></select></label><div id="edit-map" class="map-canvas" aria-label="İlan konum haritası"></div><div class="toolbar"><button type="button" id="undo-route" class="small">Son rota noktasını kaldır</button><button type="button" id="clear-map" class="small">Harita bilgilerini temizle</button></div><p id="map-summary" class="hint"></p></div></div></section><section class="panel"><h2>3. Fotoğraflar</h2><p class="muted">En fazla 5 görsel, her biri en fazla 5 MB. Yüz, plaka ve kart numaralarını gizle. Son hâlini yayımlamadan önce kontrol et.</p>${l.photos?.length?`<div class="photo-row">${l.photos.map(p=>`<div><img src="api.php?action=photo&id=${p.id}" alt="Mevcut fotoğraf"><button type="button" class="small" data-action="delete-photo" data-id="${p.id}" data-listing="${l.id}">Sil</button></div>`).join('')}</div>`:''}<label>Fotoğraf seç<input class="file-input" id="photo-input" type="file" multiple accept="image/jpeg,image/png,image/webp"></label><div id="photo-editors"></div><p class="hint">Hassas bilgi algılama otomatik değildir. Görsel üzerinde sürükleyerek seçtiğin alanı kapatabilirsin. Görseller kaydedilirken konum ve kamera metaverileri temizlenir.</p></section><section class="panel"><h2>4. Yayın alanı</h2><div class="form-grid"><label>İlan nerede görünsün?<select name="visibility">${opts({public:'Genel ağ',org:'Yalnızca kurum',both:'Genel ağ ve kurum'},l.visibility||'public')}</select></label><label>Kurum<select name="org_id" id="org-select">${opts(orgOptions,l.org_id,'Kurum seçilmedi')}</select></label><label class="full">Kurum içi konum (gizli)<select name="location_id" id="location-select"><option value="">Konum seçilmedi</option></select></label></div>${!memberships.length?'<p class="hint">Kurumda yayımlamak için önce <a href="#organizations">bir kuruma katıl</a>.</p>':''}<label class="check"><input type="checkbox" name="alert" ${Number(l.alert)?'checked':''}><span>Bulunursa haber ver: yeni benzer ilanlar için bildirim al.</span></label><div class="notice warning">Kayıp eşya için para veya hediye istemek yasaktır. Ücretsiz paylaşım ve sahiplendirmede satış yapılmaz. Bulunan bir eşya ücretsiz paylaşıma dönüştürülemez.</div><label class="check"><input type="checkbox" name="rules" required><span>İlan kurallarını kabul ediyorum; gizli ayrıntıları ve görselleri kontrol ettim.</span></label><button type="button" id="preview-listing">Yayımlanacak bilgileri önizle</button><div id="publish-preview" hidden></div><label class="check" style="margin-top:18px"><input type="checkbox" name="preview_confirm" required disabled id="preview-confirm"><span>Önizlemede herkese açık bilgileri kontrol ettim.</span></label><button class="primary" type="submit">${editId?'Değişiklikleri kaydet':'İlanı yayımla'}</button></section></form></div>`;
function fields(){const t=$('#listing-type').value;$('.health-field').hidden=!['adoption','pet_lost','pet_found'].includes(t);$('.condition-field').hidden=t!=='free';$('.secret-field').hidden=['free','adoption'].includes(t);$('.route-field').hidden=!['lost','pet_lost'].includes(t);$('.custody-field').hidden=!['found','pet_found'].includes(t);}
$('#listing-type').onchange=fields;fields();async function loadLocations(){const id=$('#org-select').value;const r=id?await api('org_panel',null,{id}):{locations:[]};$('#location-select').innerHTML=opts(Object.fromEntries(r.locations.map(p=>[p.id,p.name])),l.location_id,'Konum seçilmedi');}$('#org-select').onchange=()=>loadLocations().catch(e=>toast(e.message,true));if(l.org_id)await loadLocations();
bindEditMap(l);
$('#photo-input').onchange=async e=>{try{await addPhotos(e.target.files,5-(l.photos?.length||0));$('#preview-confirm').checked=false;$('#preview-confirm').disabled=true;}catch(err){toast(err.message,true);}e.target.value='';};
$('#listing-form').addEventListener('input',e=>{if(e.target.id!=='preview-confirm'){$('#preview-confirm').checked=false;$('#preview-confirm').disabled=true;}});
$('#preview-listing').onclick=()=>{const d=Object.fromEntries(new FormData($('#listing-form')));const box=$('#publish-preview');box.hidden=false;box.innerHTML=`<div class="notice" style="margin-top:15px"><strong>Yayımlanacak bilgiler</strong><h3>${esc(d.title||'Başlık yok')}</h3><p>${esc(types[d.type])} · ${esc(d.category)} · ${esc(d.city)} / ${esc(d.district)} · ${esc(d.event_date)}</p><p class="prewrap">${esc(d.description)}</p><p>${esc([d.color,d.brand,d.model,d.condition_text,d.health,d.custody].filter(Boolean).join(' · '))}</p><p>Görünen ad: ${esc(state.user.name)} · Yayın: ${esc({public:'Genel ağ',org:'Yalnızca kurum',both:'Genel ağ ve kurum'}[d.visibility])}</p><p>Seçtiğin ${photos.length+(l.photos?.length||0)} fotoğraf da yayımlanacak. Gizli doğrulama, rota ve özel konum notları burada görünmez.</p></div>`;$('#preview-confirm').disabled=false;};
bindForm('listing-form',async d=>{const r=await api(editId?'edit_listing':'create_listing',d);let failure='';for(const p of photos){try{const fd=new FormData();fd.set('listing_id',r.id);fd.set('photo',await canvasBlob(p.canvas),'photo.jpg');await api('upload',fd);}catch(e){failure=e.message;break;}}toast(failure?'İlan kaydedildi ancak bir fotoğraf yüklenemedi: '+failure:r.message,!!failure);location.hash='listing/'+r.id;});}
function canvasBlob(canvas){return new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.9));}
async function addPhotos(files,max=5){for(const file of files){if(photos.length>=max)throw Error('En fazla '+max+' yeni fotoğraf eklenebilir.');if(file.size>5*1024*1024||!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('JPG, PNG veya WebP; en fazla 5 MB.');const image=new Image();const url=URL.createObjectURL(file);try{await new Promise((ok,no)=>{image.onload=ok;image.onerror=no;image.src=url;});const canvas=document.createElement('canvas'),ratio=Math.min(1,1400/image.width);canvas.width=Math.round(image.width*ratio);canvas.height=Math.round(image.height*ratio);const ctx=canvas.getContext('2d');ctx.drawImage(image,0,0,canvas.width,canvas.height);const item={canvas,image};photos.push(item);const wrap=document.createElement('div');wrap.className='photo-editor';const p=document.createElement('p');p.textContent='Hassas alanı gizlemek için üzerinde sürükle.';wrap.append(p,canvas);const reset=document.createElement('button');reset.type='button';reset.className='small';reset.textContent='Gizlemeyi sıfırla';reset.onclick=()=>{ctx.drawImage(image,0,0,canvas.width,canvas.height);invalidate();};const remove=document.createElement('button');remove.type='button';remove.className='small';remove.textContent='Fotoğrafı kaldır';remove.onclick=()=>{photos=photos.filter(x=>x!==item);wrap.remove();invalidate();};const bar=document.createElement('div');bar.className='toolbar';bar.append(reset,remove);wrap.append(bar);$('#photo-editors').append(wrap);let start=null;function point(e){const r=canvas.getBoundingClientRect();return [(e.clientX-r.left)*canvas.width/r.width,(e.clientY-r.top)*canvas.height/r.height];}function invalidate(){if($('#preview-confirm')){$('#preview-confirm').checked=false;$('#preview-confirm').disabled=true;}}canvas.onpointerdown=e=>{start=point(e);canvas.setPointerCapture(e.pointerId);};canvas.onpointerup=e=>{if(!start)return;const end=point(e);ctx.fillStyle='#172033';ctx.fillRect(Math.min(start[0],end[0]),Math.min(start[1],end[1]),Math.max(8,Math.abs(end[0]-start[0])),Math.max(8,Math.abs(end[1]-start[1])));start=null;invalidate();};}finally{URL.revokeObjectURL(url);}}}
async function detail(id){const l=await api('listing',null,{id});$('#main').innerHTML=`<a class="breadcrumb" href="#home">← İlanlara dön</a><div class="detail-layout"><section class="panel">${l.photos.length?`<img id="main-photo" class="detail-photo" src="api.php?action=photo&id=${l.photos[0].id}" alt="${esc(l.title)}"><div class="photo-row">${l.photos.map(p=>`<button class="quiet small" data-photo="${p.id}" aria-label="Fotoğrafı büyüt"><img src="api.php?action=photo&id=${p.id}" alt="İlan fotoğrafı"></button>`).join('')}</div>`:''}<div style="margin-top:20px" class="toolbar">${badge(l.type)} ${badge(l.status)}</div><h1>${esc(l.title)}</h1><p class="muted">${esc(l.city)} · ${esc(l.district)} / ${esc(l.org_name||'Genel ağ')}</p><div class="detail-info"><div><span>Kategori</span>${esc(l.category)}</div><div><span>Yaklaşık tarih</span>${date(l.event_date)}</div><div><span>Renk / Marka / Model</span>${esc([l.color,l.brand,l.model].filter(Boolean).join(' · ')||'Belirtilmedi')}</div><div><span>Son geçerlilik</span>${date(l.expires_at)}</div></div><h3>Açıklama</h3><p class="prewrap">${esc(l.description)}</p>${l.latitude!==null&&l.latitude!==undefined?`<div class="map-section"><h3>${l.can_manage?'Yetkili konum ve güzergâh':'Yaklaşık konum'}</h3><p class="hint">${l.can_manage?'Bu ayrıntılar genel ziyaretçilere gösterilmez.':'Nokta yaklaşık bölgeyi gösterir; kesin teslim yeri değildir.'} Haritayı açmak OpenStreetMap bağlantısı gerektirir.</p><button id="view-map-button">Haritayı aç</button><div id="view-map" class="map-canvas" hidden></div></div>`:''}${l.condition_text?`<h3>Eşyanın durumu</h3><p>${esc(l.condition_text)}</p>`:''}${l.health?`<h3>Bakım ve sağlık bilgileri</h3><p class="prewrap">${esc(l.health)}</p>`:''}${l.custody?`<h3>Muhafaza</h3><p>${esc(l.custody)}</p>`:''}${l.can_manage?`<details class="notice"><summary>Yalnızca yetkiliye açık bilgiler</summary><p class="prewrap">Gizli doğrulama: ${esc(l.secret)}<br>Rota / sefer: ${esc(l.route)}<br>Özel konum: ${esc(l.private_location)}</p></details>`:''}</section><aside class="panel sidebar-card"><p class="eyebrow">İLAN SAHİBİ</p><h2>${esc(l.owner_name)}</h2><p class="muted">Telefon ve e-posta otomatik paylaşılmaz.</p>${l.can_manage?`<div class="toolbar"><a class="button primary" href="#edit/${l.id}">Düzenle</a><a class="button" href="#claims">Talepleri gör</a></div><div class="divider"></div><div class="toolbar"><button data-action="listing-op" data-id="${l.id}" data-op="extend">Süreyi uzat</button><button data-action="listing-op" data-id="${l.id}" data-op="close">İlanı kapat</button><button class="danger-button" data-action="listing-op" data-id="${l.id}" data-op="delete">Sil</button></div><label class="check" style="margin-top:20px"><input type="checkbox" data-alert="${l.id}" ${Number(l.alert)?'checked':''}><span>Bulunursa haber ver</span></label>`:l.status==='open'&&['found','pet_found','free','adoption'].includes(l.type)?`<button class="primary" data-action="claim" data-id="${l.id}" data-type="${l.type}">${['free','adoption'].includes(l.type)?'Talep gönder':'Sahipleniyorum'}</button>`:''}<div class="divider"></div><h3>Güvenli teslim</h3><p class="muted">Önce gizli bir ayrıntıyla sahipliği doğrula. Teslim için kurumun kayıp eşya birimini, danışmayı veya başka bir kamusal noktayı seç.</p><p class="notice warning">Para, hediye veya kapora istenmez. Şüpheli durumları bildir.</p>${!l.can_manage?`<div class="toolbar"><button class="small quiet" data-action="report" data-type="listing" data-id="${l.id}">İlanı bildir</button><button class="small quiet" data-action="report" data-type="user" data-id="${l.user_id}">Hesabı bildir</button><button class="small quiet" data-action="block" data-id="${l.user_id}">Hesabı engelle</button></div>`:''}<p class="hint" style="margin-top:18px">İlan no: #${l.id}</p></aside></div>`;bindViewMap(l);$$('[data-photo]').forEach(b=>b.onclick=()=>$('#main-photo').src='api.php?action=photo&id='+b.dataset.photo);const a=$('[data-alert]');if(a)a.onchange=async()=>{try{await api('listing_action',{id:l.id,op:'alert',enabled:a.checked});toast('Bildirim tercihi kaydedildi.');}catch(e){a.checked=!a.checked;toast(e.message,true);}};}
async function mine(){if(!needUser())return;const rows=await api('mine');$('#main').innerHTML=title('İlanlarım','İlanlarını düzenle, sürelerini uzat ve teslimleri takip et.','<a class="button primary" href="#create">+ İlan oluştur</a>')+userTabs('mine')+`<div class="card-grid">${rows.length?rows.map(l=>`<div>${card(l)}<div style="margin:8px">${badge(l.status)}</div></div>`).join(''):empty('Henüz ilan oluşturmadın.','Kaybettiğin, bulduğun veya paylaşmak istediğin bir eşya için başlayabilirsin.','<a class="button primary" href="#create">İlan oluştur</a>')}</div>`;}
async function profile(){if(!needUser())return;const u=state.user;$('#main').innerHTML=title('Profilim')+userTabs('profile')+`<div class="form-wrap panel"><form id="profile"><label>Görünen ad<input name="name" value="${esc(u.name)}" maxlength="80" required></label><label>E-posta<input value="${esc(u.email)}" readonly><small>Bu bilgi herkese açık değildir.</small></label><label class="check"><input type="checkbox" name="notifications" ${Number(u.notifications)?'checked':''}><span>Yeni eşleşmeler için bildirim almak istiyorum.</span></label><details><summary>Parolayı değiştir</summary><label>Mevcut parola<input name="current_password" type="password" autocomplete="current-password"></label><label>Yeni parola<input name="password" type="password" minlength="10" autocomplete="new-password"></label></details><div class="toolbar" style="margin-top:20px"><button class="primary">Değişiklikleri kaydet</button><button type="button" data-action="logout">Çıkış yap</button>${['admin','moderator'].includes(u.role)?'<a href="#admin" class="button">Yönetim paneli</a>':''}</div></form></div>`;bindForm('profile',async d=>{const r=await api('profile',d);await session();toast(r.message);});}
async function matches(){if(!needUser())return;const rows=await api('matches');$('#main').innerHTML=title('Olası eşleşmeler','Bu sonuçlar kesin sahiplik kanıtı değildir; her adayı ayrıca doğrula.')+userTabs('matches')+`<section class="panel">${rows.length?rows.map(r=>`<div class="row"><div>${badge('match','Benzerlik: %'+r.score)}<h3>${esc(r.found_title)}</h3><p>Kayıp ilanın: ${esc(r.lost_title)}</p></div><a class="button primary" href="#listing/${r.found_id}">İlanı incele</a></div>`).join(''):empty('Henüz olası eşleşme yok.','İlanın açık ve bildirim tercihin etkinse, uygun yeni ilanlar için haber vereceğiz.')}</section>`;}
async function notifications(){if(!needUser())return;const rows=await api('notifications');$('#main').innerHTML=title('Bildirimler')+userTabs('notifications')+`<section class="panel">${rows.length?rows.map(n=>`<div class="row"><div><h3>${esc(n.title)}</h3><p>${date(n.created_at)} ${!Number(n.is_read)?' · Yeni':''}</p></div><a class="button small" href="#${n.listing_id?'listing/'+n.listing_id:'support'}">İncele</a></div>`).join(''):empty('Yeni bildirim yok.')}</section>`;await api('read_notifications',{});$('#unread').textContent='';}
function claimRow(c){const manage=c.can_manage||Number(c.owner_id)===Number(state.user.id);return `<article class="row"><div><h3>${esc(c.title||'İlan #'+c.listing_id)}</h3><p>${esc(c.claimant_name||'Talep')} · ${date(c.created_at)} ${badge(c.status)}</p><details><summary>Gizli kanıt / talep açıklaması</summary><p class="prewrap">${esc(c.proof)}</p></details></div><div class="toolbar"><a class="button small" href="#listing/${c.listing_id}">İlan</a>${manage&&c.status==='pending'?`<button class="primary small" data-action="review" data-id="${c.id}" data-decision="accepted">Doğrula ve kabul et</button><button class="small" data-action="review" data-id="${c.id}" data-decision="rejected">Reddet</button>`:''}${['accepted','delivered'].includes(c.status)?`<a class="button primary small" href="#chat/${c.id}">Görüşme ve teslim</a>`:''}</div></article>`;}
async function claims(){if(!needUser())return;const rows=await api('claims');$('#main').innerHTML=title('Talepler ve sohbet','Gizli ayrıntıyı kontrol etmeden teslim kararı verme.')+userTabs('claims')+`<section class="panel">${rows.length?rows.map(claimRow).join(''):empty('Henüz talep veya görüşme yok.','Bir bulunan eşya ya da ücretsiz paylaşım ilanından talep gönderebilirsin.')}</section>`;}
async function chat(id){if(!needUser())return;const r=await api('messages',null,{id});const c=r.claim;$('#main').innerHTML=`<a href="#claims" class="breadcrumb">← Taleplere dön</a>${title(r.listing.title)}<div class="form-wrap"><section class="panel"><div class="notice warning">Para veya hediye istemek yasaktır. Teslimi kamusal bir noktada yapın. Çocuk adına görüşmeyi veli veya kurum yetkilisi yürütmelidir.</div>${r.listing.custody?`<p>Muhafaza: ${esc(r.listing.custody)}</p>`:''}<div id="conversation" class="conversation" aria-live="polite"></div><form id="send-message"><label>Mesajın<textarea name="body" maxlength="2000" required ${c.status!=='accepted'||Number(c.chat_closed)||r.blocked?'disabled':''}></textarea></label><button class="primary" ${c.status!=='accepted'||Number(c.chat_closed)||r.blocked?'disabled':''}>Gönder</button></form><div class="divider"></div><h3>Teslim durumu</h3><p>${badge(c.status)} · Teslim eden: ${Number(c.owner_confirm)?'Onaylandı':'Bekliyor'} · Alan: ${Number(c.claimant_confirm)?'Onaylandı':'Bekliyor'}</p><div class="toolbar">${c.status==='accepted'?`<button class="primary" data-action="delivery" data-id="${id}">Teslimi onayla</button>${r.listing.can_staff&&Number(c.user_id)!==Number(state.user.id)?`<button data-action="delivery" data-id="${id}" data-institution="1">Kurum görevlisi olarak teslim et</button>`:''}`:''}<button data-action="close-chat" data-id="${id}">Sohbeti kapat</button><button data-action="report" data-type="chat" data-id="${id}">Görüşmeyi bildir</button></div></section></div>`;let last='';function messages(items){const key=items.map(m=>m.id).join(',');if(last===key&&items.length)return;last=key;$('#conversation').innerHTML=items.length?items.map(m=>`<div class="message ${Number(m.user_id)===Number(state.user.id)?'own':''}"><small>${esc(m.name)} · ${esc(m.created_at)}</small>${esc(m.body)}</div>`).join(''):empty('Görüşme açıldı.','Teslim için güvenli bir nokta belirleyin.');$('#conversation').scrollTop=$('#conversation').scrollHeight;}messages(r.items);bindForm('send-message',async(d,f)=>{await api('send_message',{...d,id});f.reset();messages((await api('messages',null,{id})).items);});poll=setInterval(async()=>{if(document.hidden)return;try{const fresh=await api('messages',null,{id});if(fresh.claim.status!==c.status||fresh.claim.chat_closed!==c.chat_closed||fresh.blocked!==r.blocked){clearInterval(poll);route();return;}if($('#conversation'))messages(fresh.items);}catch(e){clearInterval(poll);toast(e.message,true);}},6000);}
async function organizations(){const r=await api('organizations');orgCache=r;$('#main').innerHTML=title('Kurum alanları','Okul, iş yeri ve kuruluşların kayıp eşya noktaları.')+(state.user?userTabs('organizations'):'')+`${r.memberships.length?`<section class="panel"><h2>Katıldığım kurumlar</h2>${r.memberships.map(m=>`<div class="row"><div><h3>${esc(m.name)}</h3><p>${esc(roles[m.role])} · ${badge(m.org_status==='approved'?m.status:m.org_status)}</p></div><div class="toolbar">${m.status==='approved'&&m.org_status==='approved'?`<a class="button primary" href="#org/${m.org_id}">Kurum alanını aç</a>`:''}${m.role!=='org_admin'?`<button class="small" data-action="leave-org" data-id="${m.org_id}">Ayrıl</button>`:''}</div></div>`).join('')}</section>`:''}<div class="detail-layout"><section class="panel"><h2>Kurumları keşfet</h2>${r.items.length?r.items.map(o=>`<div class="row"><div><h3>${esc(o.name)}</h3><p>${esc(o.kind)} · ${esc(o.city)}</p></div><div class="toolbar"><a class="button small" href="#home?org_id=${o.id}">İlanlar</a><button class="small primary" data-action="join-org" data-id="${o.id}">Katıl</button></div></div>`).join(''):empty('Henüz onaylanmış kurum yok.')}</section><section class="panel sidebar-card"><h2>Kurumun için alan aç</h2><p class="muted">Başvuru platform yöneticisi tarafından incelenir. Onaydan sonra kurum yapısını ve çalışan yetkilerini yönetebilirsin.</p><form id="create-org"><label>Kurum adı<input name="name" required maxlength="120"></label><label>Kurum türü<select name="kind" required>${opts(['Okul','Şirket','Hastane','Belediye','Otobüs firması','Diğer'])}</select></label><label>Şehir<select name="city" required>${opts(cities)}</select></label><button class="primary">Kurum başvurusu oluştur</button></form></section></div>`;bindForm('create-org',async d=>{if(!needUser())return;const r=await api('create_org',d);toast(r.message);route();});}
async function orgPanel(id){if(!needUser())return;const r=await api('org_panel',null,{id}),m=r.membership;const locOpts=Object.fromEntries(r.locations.map(p=>[p.id,`${p.name} (${({branch:'Şube',building:'Bina',floor:'Kat',room:'Oda'})[p.kind]})`]));$('#main').innerHTML=`<a href="#organizations" class="breadcrumb">← Kurumlarım</a>${title(r.org.name,roles[m.role]+' · '+r.org.city,`<a href="#home?org_id=${id}" class="button">Kurum ilanları</a>`)}<div class="notice">Kurum → Şube / kampüs → Bina → Kat → Bölüm / oda. Tam konumlar genel ilanlarda paylaşılmaz.</div>${m.role==='org_admin'?`<section class="panel"><div class="section-title"><h2>Üyeler ve başvurular</h2><button data-action="invite" data-id="${id}">Davet kodu oluştur</button></div><div class="table-wrap"><table><thead><tr><th>Üye</th><th>Yetki</th><th>Konum</th><th>İşlem</th></tr></thead><tbody>${r.members.map(x=>`<tr><td>${esc(x.name)}<br>${badge(x.status)}</td><td><select id="role-${x.id}">${opts({member:roles.member,staff:roles.staff,location_admin:roles.location_admin,org_admin:roles.org_admin},x.role)}</select></td><td><select id="loc-${x.id}">${opts(locOpts,x.location_id,'Kurum geneli')}</select></td><td><div class="toolbar"><button class="small" data-action="member" data-id="${x.id}" data-org="${id}" data-op="save">Onayla / Kaydet</button><button class="small danger-button" data-action="member" data-id="${x.id}" data-org="${id}" data-op="remove">Çıkar</button></div></td></tr>`).join('')}</tbody></table></div></section>`:''}${['org_admin','location_admin'].includes(m.role)?`<section class="panel"><h2>Kurum yapısı</h2><div class="form-grid"><div>${r.locations.length?r.locations.map(p=>`<p style="margin-left:${({branch:0,building:12,floor:24,room:36})[p.kind]}px">${esc(locOpts[p.id])}${p.parent_id?` <small class="muted"> / ${esc(locOpts[p.parent_id])}</small>`:''}</p>`).join(''):'<p class="muted">İlk şubeyi ekleyerek başlayın.</p>'}</div><form id="add-location"><input type="hidden" name="org_id" value="${id}"><label>Konum adı<input name="name" maxlength="100" required></label><label>Tür<select name="kind" required>${opts({branch:'Şube / kampüs',building:'Bina',floor:'Kat',room:'Bölüm / oda'})}</select></label><label>Üst konum<select name="parent_id">${opts(locOpts,'','Kurum (ilk şube için)')}</select></label><button class="primary">Konum ekle</button></form></div></section>`:''}<section class="panel"><h2>Yetkili olduğum ilanlar</h2>${r.listings.length?r.listings.map(l=>`<div class="row"><div><h3>${esc(l.title)} ${badge(l.status)}</h3><p>${esc(l.private_location||'')}</p></div><a class="button" href="#listing/${l.id}">İncele / düzenle</a></div>`).join(''):empty('Bu alanda yönettiğin ilan yok.')}<a class="button primary" href="#create">+ İlan ekle</a></section><section class="panel"><h2>Sahiplik ve teslim talepleri</h2>${r.claims.length?r.claims.map(claimRow).join(''):empty('Bekleyen talep yok.')}</section>`;bindForm('add-location',async d=>{const res=await api('org_location',d);toast(res.message);route();});}
async function support(){if(!needUser())return;photos=[];const r=await api('tickets');$('#main').innerHTML=title('Destek ve başvurularım','Teknik sorun ve öneriler, güvenlik şikâyetlerinden ayrı değerlendirilir.')+userTabs('support')+`<div class="detail-layout"><section class="panel"><h2>Başvurularım</h2>${r.tickets.length?r.tickets.map(t=>`<article class="row"><div><h3>#${t.id} · ${esc(t.subject)} ${badge(t.status)}</h3><p class="prewrap">${esc(t.body)}</p>${t.reply?`<div class="notice prewrap">Yanıt: ${esc(t.reply)}</div>`:''}<div class="photo-row">${t.photos.map(p=>`<a target="_blank" href="api.php?action=photo&id=${p.id}"><img src="api.php?action=photo&id=${p.id}" alt="Destek eki"></a>`).join('')}</div></div></article>`).join(''):empty('Henüz destek başvurun yok.')}<h2 style="margin-top:25px">Güvenlik şikâyetlerim</h2>${r.reports.length?r.reports.map(t=>`<article class="row"><div><h3>${esc(t.reason)} ${badge(t.status)}</h3><p>${esc(t.body)}</p>${t.reply?`<div class="notice prewrap">Yanıt: ${esc(t.reply)}</div>`:''}</div></article>`).join(''):'<p class="muted">Açılmış şikâyet yok.</p>'}<h2 style="margin-top:25px">Engellediğim hesaplar</h2>${r.blocks.map(b=>`<div class="row"><span>${esc(b.name)}</span><button class="small" data-action="unblock" data-id="${b.target_id}">Engeli kaldır</button></div>`).join('')||'<p class="muted">Engellenen hesap yok.</p>'}</section><section class="panel sidebar-card"><h2>Hata bildir / öneri gönder</h2><form id="support"><label>Konu<input name="subject" maxlength="120" required></label><label>Açıklama<textarea name="body" maxlength="3000" required></textarea></label><label>Ekran görüntüsü (isteğe bağlı)<input type="file" id="photo-input" multiple accept="image/jpeg,image/png,image/webp"></label><div id="photo-editors"></div><button class="primary">Başvuru gönder</button></form></section></div>`;$('#photo-input').onchange=e=>addPhotos(e.target.files).catch(err=>toast(err.message,true));bindForm('support',async d=>{const result=await api('ticket',d);let err='';for(const p of photos){try{const fd=new FormData();fd.set('ticket_id',result.id);fd.set('photo',await canvasBlob(p.canvas),'support.jpg');await api('upload',fd);}catch(e){err=e.message;break;}}toast(err?'Başvuru açıldı; ek yüklenemedi: '+err:result.message,!!err);route();});}
const adminSections={overview:'Genel bakış',users:'Kullanıcılar',orgs:'Kurumlar',listings:'İlanlar',animals:'Hayvan güvenliği',reports:'Şikâyetler',tickets:'Destek',settings:'Ayarlar',audit:'İşlem kayıtları'};
async function adminPanel(section='overview'){if(!state.user){sessionStorage.setItem('v404-admin-login','1');location.hash='login';return;}if(!['admin','moderator'].includes(state.user.role))throw Error('Yönetim paneline erişim yetkiniz yok.');const data=await api('admin_panel',null,{section});const allowed=state.user.role==='admin'?Object.keys(adminSections):['overview','listings','animals','reports'];let content='';
if(section==='overview')content=`<div class="stats">${[['users','Kullanıcı'],['listings','Açık ilan'],['reports','Açık şikâyet'],['delivered','Tamamlanan teslim']].map(([key,label])=>`<div class="panel"><span>${label}</span><strong>${data[key]}</strong></div>`).join('')}</div><section class="panel" style="margin-top:22px"><h2>İnceleme ve güvenlik</h2><p class="muted">Yeni kurum başvurularını ve güvenlik şikâyetlerini inceleyin. Sahipliği yeterli kanıt olmadan doğrulamayın. Yönetim işlemleri kayıt altına alınır.</p><div class="toolbar"><a href="#admin/reports" class="button primary">Şikâyetleri incele</a><a href="#admin/animals" class="button">Hayvan güvenliği kuyruğu</a></div></section>`;
if(['users','orgs','listings','animals'].includes(section)){let headers=[],rows=[];if(section==='users'){headers=['Kullanıcı','E-posta / rol','Durum','İşlemler'];rows=data.map(u=>[`${esc(u.name)}<br><small>#${u.id} · ${Number(u.verified)?'E-posta doğrulandı':'Doğrulanmadı'}</small>`,`${esc(u.email)}<br>${esc(roles[u.role])}`,badge(u.status),`<button class="small" data-action="admin-user" data-id="${u.id}" data-role="${u.role}" data-status="${u.status}">Yönet</button>`]);}else if(section==='orgs'){headers=['Kurum','Tür / şehir','Durum','İşlemler'];rows=data.map(o=>[esc(o.name),esc(o.kind)+' / '+esc(o.city),badge(o.status),`<div class="toolbar"><button class="small primary" data-action="admin-simple" data-op="org" data-id="${o.id}" data-status="approved">Onayla</button><button class="small" data-action="admin-simple" data-op="org" data-id="${o.id}" data-status="rejected">Reddet</button></div>`]);}else{headers=['İlan','Tür / şehir','Durum','İşlemler'];rows=data.map(l=>[`<a href="#listing/${l.id}">${esc(l.title)}</a><br><small>#${l.id} · Kullanıcı #${l.user_id}</small>`,`${badge(l.type)}<br>${esc(l.city)}`,badge(l.status),`<div class="toolbar"><button class="small" data-action="admin-simple" data-op="listing" data-id="${l.id}" data-status="hidden">Gizle</button><button class="small" data-action="admin-simple" data-op="listing" data-id="${l.id}" data-status="closed">Kapat</button><button class="small" data-action="admin-simple" data-op="listing" data-id="${l.id}" data-status="open">Aç</button></div>`]);}content=table(headers,rows);}
if(section==='reports')content=`<section class="panel">${data.length?data.map(r=>`<article class="row"><div><h3>#${r.id} · ${esc(r.reason)} ${badge(r.status)}</h3><p>${esc(r.reporter)} · ${esc({listing:'İlan',user:'Hesap',chat:'Sohbet'}[r.target_type])} #${r.target_id}</p><p class="prewrap">${esc(r.body)}</p>${r.reply?`<p>Yanıt: ${esc(r.reply)}</p>`:''}</div><div class="toolbar"><button class="small" data-action="report-inspect" data-id="${r.id}">İçeriği incele</button><button class="small primary" data-action="admin-reply" data-id="${r.id}" data-op="report">Yanıtla / Durum</button>${r.target_type==='user'?`<button class="small" data-action="restrict-user" data-id="${r.target_id}">Hesabı kısıtla</button>`:''}${r.target_type==='chat'?`<button class="small danger-button" data-action="admin-simple" data-op="chat" data-id="${r.target_id}">Sohbeti kapat</button>`:''}${r.target_type==='listing'?`<button class="small danger-button" data-action="admin-simple" data-op="listing" data-id="${r.target_id}" data-status="hidden">İlanı gizle</button>`:''}</div></article>`).join(''):empty('Şikâyet kuyruğu boş.')}</section>`;
if(section==='tickets')content=`<section class="panel">${data.length?data.map(t=>`<article class="row"><div><h3>#${t.id} · ${esc(t.subject)} ${badge(t.status)}</h3><p>${esc(t.name)}</p><p class="prewrap">${esc(t.body)}</p>${t.reply?`<p class="notice">${esc(t.reply)}</p>`:''}<div class="photo-row">${t.photos.map(p=>`<a target="_blank" href="api.php?action=photo&id=${p.id}"><img src="api.php?action=photo&id=${p.id}" alt="Destek eki"></a>`).join('')}</div></div><button class="primary small" data-action="admin-reply" data-op="ticket" data-id="${t.id}">Yanıtla / Durum</button></article>`).join(''):empty('Destek kaydı yok.')}</section>`;
if(section==='audit')content=table(['İşlem','Yetkili','Hedef','Tarih'],data.map(a=>[esc(a.action),esc(a.name),esc(a.target_id||'—'),esc(a.created_at)]));
if(section==='settings'){const settings=Object.fromEntries(data.map(x=>[x.name,x.value]));content=`<section class="panel form-wrap"><form id="announcement-form"><h2>Site duyurusu</h2><label>Duyuru metni<textarea name="value" maxlength="1000">${esc(settings.announcement)}</textarea><small>Boş bırakırsanız duyuru görünmez.</small></label><button class="primary">Duyuruyu kaydet</button></form><div class="divider"></div><form id="registration-form"><label>Yeni hesap kaydı<select name="value">${opts({'1':'Açık','0':'Kapalı'},settings.registration_open)}</select></label><button>Kaydet</button></form></section>`;}
$('#main').innerHTML=title('Platform yönetimi',adminSections[section]||'Genel bakış','<a href="#home" class="button">Siteye dön</a>')+`<nav class="tabs" aria-label="Yönetim bölümleri">${allowed.map(s=>`<a href="#admin/${s}" class="${section===s?'active':''}">${adminSections[s]}</a>`).join('')}</nav>`+content;if(section==='settings'){bindForm('announcement-form',async d=>{await api('admin_action',{op:'settings',name:'announcement',...d});await session();toast('Duyuru kaydedildi.');});bindForm('registration-form',async d=>{await api('admin_action',{op:'settings',name:'registration_open',...d});toast('Kayıt ayarı güncellendi.');});}}
function table(headers,rows){return `<section class="panel"><div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(row=>`<tr>${row.map(cell=>`<td>${cell}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}">Kayıt bulunamadı.</td></tr>`}</tbody></table></div>${rows.length===500?'<p class="hint">Son 500 kayıt gösteriliyor.</p>':''}</section>`;}
function staticPage(which){const pages={guide:`<p class="eyebrow">NASIL ÇALIŞIR?</p><h1>Birbirimizi bulalım.</h1><h2>1. Kaybettim veya Buldum</h2><p>Eşyanın kategorisini, yaklaşık tarihini ve bölgesini yaz. Fotoğraf ekleyebilirsin. Yalnızca sahibinin bileceği ayrıntıyı gizli doğrulama alanında tut.</p><h2>2. Olası eşleşmeler</h2><p>Sistem kategori, şehir, tarih, renk, marka, model, açıklama ve güzergâhtaki bölge adlarını karşılaştırır. Benzer ilanları olasılık olarak gösterir; sahipliğe kendisi karar vermez. “Bulunursa haber ver” açık olduğunda yeni eşleşme bildirimi gelir.</p><h2>3. Sahiplik ve özel görüşme</h2><p>Bulunan eşya ilanında “Sahipleniyorum” seçeneğiyle kanıtını gönder. İlan sahibi veya yetkili kurum görevlisi değerlendirir. Kabul edilirse yalnızca bu ilana ait sohbet açılır. Yeterli kanıt yoksa teslim yapılmaz.</p><h2>4. Güvenli teslim</h2><p>Kurum danışması, güvenlik noktası veya başka bir kamusal yerde buluşun. İki taraf teslimi onayladığında ilan kapanır. Kurum görevlisi kendi yetkisi içindeki teslimi panelinden tamamlayabilir.</p><h2>Ücretsiz paylaşım ve hayvanlar</h2><p>Kullanmadığın eşyayı ücretsiz ver veya ücretsiz sahiplendirme ilanı aç. Birden fazla talep arasından alıcıyı seçebilirsin. Kayıp ve bulunan hayvanlar ayrı ilan türleriyle aranır.</p><a class="button primary" href="#create">İlan oluştur</a>`,rules:`<p class="eyebrow">GÜVENLİK VE KULLANIM</p><h1>İyi niyet, açık kurallar.</h1><ul><li>Bulunan eşya için para, hediye, kapora veya başka karşılık istemek yasaktır.</li><li>Ücretsiz eşya ve hayvan sahiplendirmede satış, açık artırma ve ücretli rezervasyon yoktur. Platform ödeme, kargo veya hayvan taşıma hizmeti sunmaz.</li><li>Bulduğun bir başkasına ait eşyayı ücretsiz paylaşıma çeviremezsin.</li><li>Silah, ilaç, patlayıcı, tehlikeli madde ve uygun olmayan ürünler paylaşılamaz.</li><li>Açık ilanlarda telefon, e-posta, sosyal medya hesabı ve ev adresi paylaşma. Kimlik, plaka, kart numarası ve yüzleri fotoğraf yayımlanmadan önce gizle.</li><li>E-posta doğrulaması hesap kontrolünü gösterir; kişinin güvenilirliğinin kanıtı değildir.</li><li>Çocuklar ilanları inceleyebilir. İlan, sohbet ve teslimi veli hesabı veya okulun yetkili çalışanı yürütür. Bu sürümde bağımsız çocuk hesabı açılmaz.</li><li>Birden çok sahiplik iddiasını ayrı değerlendir. Kanıt yetersizse teslim etme; kurum veya güvenlik moderatörüne başvur.</li><li>Tehdit, yanlış sahiplik, sahte ilan, para isteme ve hayvan güvenliği endişelerini ilan, hesap veya sohbet üzerinden bildir.</li></ul><h2>İlan süreleri</h2><p>Kayıp / bulunan eşya 90 gün; ücretsiz paylaşım 30 gün; kayıp / bulunan hayvan 60 gün; sahiplendirme 30 gün açık kalır. Süre dolduğunda ilan arşivlenir ve yeni eşleşme bildirimi durur. İlanlarım’dan uzatabilir, kapatabilir veya silebilirsin.</p><h2>Sorun yaşarsan</h2><p>Bir hesabı engelleyebilir ve görüşmeyi kapatabilirsin. Güvenlik şikâyetleri ayrı kuyruğa gider. Teknik hata ve öneri için Destek bölümünü kullan.</p>`,privacy:`<p class="eyebrow">GİZLİLİK</p><h1>Gerekli bilgi, doğru kişiyle.</h1><h2>Herkese açık bilgiler</h2><p>İlan başlığı, açıklaması, fotoğrafları, türü, kategorisi, görünen ad, yaklaşık tarih, şehir / bölge ve genel muhafaza bilgisi ilanın seçilen yayın alanında görünür. Kuruma özel ilanları yalnızca onaylı üyeler görebilir.</p><h2>Gizli bilgiler</h2><p>E-posta herkese gösterilmez. Parolalar tek yönlü özetlenir. İlanın gizli doğrulama bilgisi, rota ve özel konum notu yalnızca ilan sahibi ve yetkili kurum çalışanı tarafından görülür. Sistem rotayı canlı takip etmez; yalnızca eşleşme hesabında kullanır.</p><h2>Talep ve görüşme</h2><p>Sahiplik başvurusunda gönderdiğin kanıt, başvurunun karşı tarafına ve yetkili kurum görevlisine gösterilir. Sohbet yalnızca kabul edilen talebe bağlıdır. Şikâyet edilen görüşme güvenlik moderatörü tarafından incelenebilir; bu erişim kayda alınır.</p><h2>Yerel kayıtlar ve saklama</h2><p>Bu kurulum ilan ve hesap verilerini kendi MySQL veritabanında ve uploads klasöründe saklar. Silinen ilanın gizli ayrıntıları hemen boşaltılır ve ilan görünmez olur. Süresi dolan ilanlar arşivlenir. Kapanan / silinen ilanların özel bilgileri, fotoğrafları ve mesajları 180 gün sonra bakım göreviyle temizlenir. Güvenlik ve yönetim kayıtları 365 gün saklanır. Otomatik temizlik için README’deki bakım görevini etkinleştirmek gerekir.</p><h2>Hesap ve silme başvurusu</h2><p>Görünen ad ve bildirim tercihini Profilim’den değiştirebilirsin. Hesabınla ilgili düzeltme veya kişisel veri silme isteğini Destek üzerinden gönderebilirsin. Operatör, bakım aracındaki kullanıcı anonimleştirme komutuyla isteği yerine getirir.</p><h2>Tarayıcı ve dış hizmetler</h2><p>Oturum için gerekli çerez, tema için tarayıcı depolaması kullanılır. Reklam veya analiz izleyicisi yoktur. Görseller yeniden kaydedilirken EXIF verileri kaldırılır. Haritayı açmayı seçersen tarayıcın OpenStreetMap sunucusundan harita parçalarını alır; bu servis IP adresini ve görüntülenen harita alanını görebilir. Canlı konum takibi yapılmaz.</p>`};$('#main').innerHTML=`<article class="prose panel">${pages[which]}</article>`;}
async function animals(){const data=await api('listings',null,{type:'pet_lost'});$('#main').innerHTML=title('Hayvanlar','Kayıp dostlarımızı bulalım; sahiplendirmeyi güvenle yapalım.')+`<div class="action-grid animal-actions">${[['pet_lost','Kayıp hayvan'],['pet_found','Bulunan hayvan'],['adoption','Ücretsiz sahiplendirme']].map(([t,n])=>`<a href="#create/${t}" class="action-card"><span class="action-icon">${icon('pet')}</span><strong>${n} ilanı</strong></a>`).join('')}</div><div class="tabs">${['pet_lost','pet_found','adoption'].map(t=>`<a href="#home?type=${t}">${types[t]} ilanlarını ara</a>`).join('')}</div><div class="notice">Ücretli sahiplendirme veya hayvan satışı yapılmaz. Sağlık ve bakım bilgilerini açıkça paylaş; ev adresini gizli tut.</div><h2>Son kayıp hayvan ilanları</h2><div class="card-grid">${data.items.length?data.items.map(card).join(''):empty('Henüz kayıp hayvan ilanı yok.')}</div>`;}
async function route(){clearInterval(poll);const token=++renderToken;const [path,query='']=location.hash.slice(1).split('?'),[page='home',id]=path.split('/');$('#main').innerHTML='<div class="loading">Yükleniyor…</div>';window.scrollTo(0,0);try{if(!state.ready){$('#main').innerHTML=`<section class="setup panel"><h1>V-404 kuruluma hazır.</h1><p>WampServer üzerinden ilk yönetici hesabını oluştur ve veritabanını kur.</p><a class="button primary" href="setup.php">Kurulumu başlat</a></section>`;return;}switch(page||'home'){case'home':await home(new URLSearchParams(query));break;case'login':case'register':await auth(page);break;case'verify':await verify();break;case'create':await create(id);break;case'edit':await create('lost',id);break;case'listing':await detail(id);break;case'mine':await mine();break;case'profile':await profile();break;case'matches':await matches();break;case'notifications':await notifications();break;case'claims':await claims();break;case'chat':await chat(id);break;case'organizations':await organizations();break;case'org':await orgPanel(id);break;case'support':await support();break;case'admin':await adminPanel(id);break;case'animals':await animals();break;case'guide':case'rules':case'privacy':staticPage(page);break;default:$('#main').innerHTML=empty('Sayfa bulunamadı.','','<a class="button" href="#home">Ana sayfa</a>');}document.title='V-404 • '+($('#main h1')?.textContent||'Kaybolduysa, burada bul.');window.dispatchEvent(new CustomEvent('v404:route-ready',{detail:{page:page||'home',user:state.user,ready:state.ready}}));}catch(e){if(token===renderToken)$('#main').innerHTML=`<section class="panel"><h1>Bu sayfa açılamadı.</h1><p class="notice danger">${esc(e.message)}</p><div class="toolbar"><a href="#home" class="button">Ana sayfaya dön</a><button data-action="reload">Tekrar dene</button></div></section>`;window.dispatchEvent(new CustomEvent('v404:route-ready',{detail:{page:page||'home',user:state.user,ready:state.ready,failed:true}}));}}
async function confirmDialog(message,fn){modal(`<h2>İşlemi onayla</h2><p>${esc(message)}</p><button class="primary" id="confirm-action">Onayla</button>`);$('#confirm-action').onclick=async e=>{e.target.disabled=true;try{await fn();$('#modal').close();}catch(err){toast(err.message,true);}finally{e.target.disabled=false;}};}
document.addEventListener('click',async event=>{const b=event.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=b.dataset.id;try{
if(a==='filters')$('.filters').classList.toggle('show');
if(a==='reload')route();
if(a==='logout'){await api('logout',{});await session();location.hash='home';}
if(a==='resend'){const r=await api('resend',{});localCode=r.local_code||'';if($('#local-code'))$('#local-code').textContent=localCode;toast(r.message||'Yeni kod hazır.');}
if(a==='listing-op')confirmDialog({delete:'İlan silinecek ve gizli ayrıntıları temizlenecek.',close:'İlan kapatılacak; yeni talep ve mesaj alınmayacak.',extend:'İlanın süresi türüne göre yeniden başlatılacak.'}[b.dataset.op],async()=>{const r=await api('listing_action',{id,op:b.dataset.op});toast(r.message);if(b.dataset.op==='delete')location.hash='mine';else route();});
if(a==='delete-photo')confirmDialog('Fotoğraf ilandan silinecek.',async()=>{await api('delete_photo',{id});location.hash='edit/'+b.dataset.listing;route();});
if(a==='claim'){if(!needUser())return;const free=['free','adoption'].includes(b.dataset.type);modal(`<h2>${free?'Talep gönder':'Sahipliği doğrula'}</h2><p>${free?'İlan sahibine talebini ve uygun teslim zamanını anlat.':'Yalnızca gerçek sahibinin bileceği ayrıntıyı yaz. Bu yanıt ilan sorumlusu tarafından incelenir.'}</p><form id="claim-form"><label>${free?'Talep açıklaması':'Gizli kanıtın'}<textarea name="proof" required maxlength="2000"></textarea></label><button class="primary">İncelemeye gönder</button></form>`);bindForm('claim-form',async d=>{const r=await api('claim',{...d,listing_id:id});$('#modal').close();toast(r.message);location.hash='claims';});}
if(a==='review')confirmDialog(b.dataset.decision==='accepted'?'Kanıtı yeterli bulduğunu onaylıyor musun? Seçilen kişiyle görüşme açılır; diğer talepler reddedilir.':'Bu talep reddedilecek.',async()=>{const r=await api('review_claim',{id,decision:b.dataset.decision});toast(r.message);route();});
if(a==='delivery')confirmDialog(b.dataset.institution?'Kurum görevlisi olarak teslimin yapıldığını kaydediyorsun. Yetkin varsa ilan doğrudan kapanır.':'Eşyanın fiziksel olarak teslim edildiğini onaylıyor musun?',async()=>{const r=await api('delivery',{id,institution_delivery:!!b.dataset.institution});toast(r.message);route();});
if(a==='close-chat')confirmDialog('Bu görüşme yeni mesajlara kapatılacak.',async()=>{await api('close_chat',{id});route();});
if(a==='report'){if(!needUser())return;modal(`<h2>Güvenlik bildirimi</h2><form id="report-form"><label>Neden<select name="reason" required>${opts(['Para veya hediye isteme','Sahte ilan','Yanlış sahiplik iddiası','Rahatsız etme veya tehdit','Yasaklı içerik','Hayvan güvenliğiyle ilgili endişe','Diğer'])}</select></label><label>Açıklama<textarea name="body" required maxlength="2000"></textarea></label><button class="primary">Şikâyeti gönder</button></form>`);bindForm('report-form',async d=>{const r=await api('report',{...d,target_type:b.dataset.type,target_id:id});$('#modal').close();toast(r.message);});}
if(a==='block'||a==='unblock'){if(!needUser())return;confirmDialog(a==='block'?'Bu hesapla aranızdaki yeni görüşmeler ve ilan görünürlüğü kısıtlanacak.':'Bu hesabın engeli kaldırılacak.',async()=>{const r=await api('block',{target_id:id,remove:a==='unblock'});toast(r.message);route();});}
if(a==='join-org'){if(!needUser())return;modal(`<h2>Kuruma katıl</h2><p>Davet kodu varsa hemen katılabilirsin. Kod olmadan başvurun kurum yöneticisinin onayına gider.</p><form id="join-form"><label>Davet kodu (isteğe bağlı)<input name="code" maxlength="100" autocomplete="off"></label><button class="primary">Başvur / Katıl</button></form>`);bindForm('join-form',async d=>{const r=await api('join_org',{...d,org_id:id});$('#modal').close();toast(r.message);route();});}
if(a==='leave-org')confirmDialog('Kurum üyeliğinden ayrılacaksın.',async()=>{await api('leave_org',{org_id:id});route();});
if(a==='invite'){const r=await api('org_invite',{org_id:id});modal(`<h2>Tek kullanımlık davet</h2><p>${esc(r.message)}</p><p class="code">${esc(r.code)}</p><p class="hint">Bu kod üyelik sağlar; çalışan yetkisini üyeler bölümünden ayrıca tanımlayın.</p>`);}
if(a==='member'){const run=async()=>{const r=await api('org_member',{id,org_id:b.dataset.org,op:b.dataset.op,role:$('#role-'+id).value,location_id:$('#loc-'+id).value});toast(r.message);route();};if(b.dataset.op==='remove')confirmDialog('Üye kurumdan çıkarılacak.',run);else await run();}
if(a==='admin-simple')confirmDialog('Yönetim işlemi uygulanacak ve işlem kaydına eklenecek.',async()=>{await api('admin_action',{id,op:b.dataset.op,status:b.dataset.status});toast('İşlem tamamlandı.');route();});
if(a==='admin-user'){modal(`<h2>Hesap yönetimi</h2><form id="admin-user"><label>Hesap durumu<select name="status" required>${opts({active:'Aktif',restricted:'Geçici kısıtlama',closed:'Hesabı kapat'},b.dataset.status)}</select></label><label>Platform rolü<select name="role" required>${opts({user:roles.user,moderator:roles.moderator,admin:roles.admin},b.dataset.role)}</select></label><button class="primary">Değişiklikleri uygula</button></form>`);bindForm('admin-user',async d=>{await api('admin_action',{...d,id,op:'user'});$('#modal').close();route();});}
if(a==='restrict-user')confirmDialog('Bu hesabın ilan açma ve mesajlaşma yetkisi kısıtlanacak.',async()=>{await api('admin_action',{op:'user',id,status:'restricted'});toast('Hesap kısıtlandı.');});
if(a==='admin-reply'){modal(`<h2>Başvuruyu yanıtla</h2><form id="admin-reply"><label>Durum<select name="status" required>${opts({reviewing:'İnceleniyor',resolved:'Çözüldü',open:'Açık'},'reviewing')}</select></label><label>Kullanıcıya yanıt<textarea name="reply" maxlength="3000" required></textarea></label><button class="primary">Kaydet ve bildirim gönder</button></form>`);bindForm('admin-reply',async d=>{await api('admin_action',{...d,id,op:b.dataset.op});$('#modal').close();route();});}
if(a==='report-inspect'){const r=await api('admin_panel',null,{section:'report_detail',id});modal(`<h2>Şikâyet edilen içerik</h2><p class="hint">İnceleme erişiminiz kayıt altına alındı.</p><div class="prewrap">${esc(JSON.stringify(r.content,null,2))}</div>`);}
}catch(e){toast(e.message,true);}});
let theme=localStorage.getItem('v404-theme')||'light';function applyTheme(){document.documentElement.dataset.theme=theme;$('#theme').textContent=theme==='light'?'☾':'☀';$('#theme').setAttribute('aria-label',theme==='light'?'Koyu temaya geç':'Açık temaya geç');}applyTheme();$('#theme').onclick=()=>{theme=theme==='light'?'dark':'light';localStorage.setItem('v404-theme',theme);applyTheme();};
window.addEventListener('hashchange',()=>{if($('#modal').open)$('#modal').close();route();});
(async()=>{try{await session();await route();if(state.user){const n=await api('notifications');const count=n.filter(x=>!Number(x.is_read)).length;$('#unread').textContent=count||'';}}catch(e){$('#main').innerHTML=`<section class="panel"><h1>Bağlantı kurulamadı.</h1><p class="notice danger">${esc(e.message)}</p><a class="button primary" href="setup.php">Kurulumu kontrol et</a></section>`;}})();

function makeMap(element,center,zoom){if(!window.L)throw Error('Harita dosyası yüklenemedi. Sayfayı yenileyin.');const map=L.map(element,{scrollWheelZoom:false}).setView(center,zoom);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a> contributors'}).addTo(map);return map;}
function bindEditMap(l){let map,layer;let points=[];try{points=JSON.parse(l.route_points||'[]');}catch{}let point=l.latitude!=null&&l.longitude!=null?[Number(l.latitude),Number(l.longitude)]:null;function sync(){const f=$('#listing-form');f.elements.latitude.value=point?point[0]:'';f.elements.longitude.value=point?point[1]:'';f.elements.route_points.value=JSON.stringify(points);$('#map-summary').textContent=(point?'Konum seçildi. ':'Konum seçilmedi. ')+points.length+' özel rota noktası';if($('#preview-confirm')){$('#preview-confirm').checked=false;$('#preview-confirm').disabled=true;}draw();}function draw(){if(!map)return;layer.clearLayers();if(point)L.circleMarker(point,{radius:9,color:'#E53935',fillColor:'#E53935',fillOpacity:1}).addTo(layer).bindTooltip('İlgili konum');if(points.length)L.polyline(points,{color:'#0A2244',weight:4}).addTo(layer);points.forEach((p,i)=>L.circleMarker(p,{radius:5,color:'#0A2244',fillOpacity:1}).addTo(layer).bindTooltip('Rota noktası '+(i+1)));}
$('#open-map').onclick=()=>{try{$('#map-controls').hidden=false;$('#open-map').hidden=true;map=makeMap('edit-map',point||[39.0,35.0],point?13:6);layer=L.layerGroup().addTo(map);draw();map.on('click',e=>{const next=[Number(e.latlng.lat.toFixed(7)),Number(e.latlng.lng.toFixed(7))];if($('#map-mode').value==='route'){if(points.length>=30){toast('En fazla 30 rota noktası eklenebilir.',true);return;}points.push(next);}else point=next;sync();});$('#map-summary').textContent=points.length+' özel rota noktası. Haritada bir noktaya tıklayın.';}catch(e){toast(e.message,true);}};$('#undo-route').onclick=()=>{points.pop();sync();};$('#clear-map').onclick=()=>{point=null;points=[];sync();};}
function bindViewMap(l){const b=$('#view-map-button');if(!b)return;b.onclick=()=>{try{b.hidden=true;$('#view-map').hidden=false;const point=[Number(l.latitude),Number(l.longitude)],map=makeMap('view-map',point,l.can_manage?14:12);const found=['found','pet_found'].includes(l.type);const color=found?'#167D5A':'#E53935';L.circleMarker(point,{radius:9,color,fillColor:color,fillOpacity:1}).addTo(map).bindTooltip(l.can_manage?'Yetkili konum':'Yaklaşık bölge');if(!l.can_manage)L.circle(point,{radius:800,color,weight:1,fillOpacity:.08}).addTo(map);if(l.can_manage&&l.route_points){const points=JSON.parse(l.route_points);if(points.length)L.polyline(points,{color:'#0A2244',weight:4}).addTo(map);}}catch(e){toast(e.message,true);}};}
